SELECT CASE WHEN p.price >= 1050 THEN 'high' WHEN p.price >= 420 THEN 'mid' ELSE 'low' END price_bucket, SUM(oi.unit_price * oi.quantity) revenue, ROUND(STDDEV(oi.unit_price), 2) stddev_unit_price FROM order_items oi INNER JOIN products p ON p.id = oi.product_id LEFT JOIN orders o ON o.id = oi.order_id WHERE oi.order_id IN (5, 9, 38) GROUP BY CASE WHEN p.price >= 1050 THEN 'high' WHEN p.price >= 420 THEN 'mid' ELSE 'low' END
